// SearchShopProducts is the resolver for the searchShopProducts field.
func (r *queryResolver) SearchShopProducts(ctx context.Context, shopID string, query string, limit int, offset int, visualCandidates []string) (*model.PaginatedPublicProducts, error) {
	normalizedQuery := utils.NormalizeSearchText(query)

	if len(visualCandidates) == 1 && visualCandidates[0] == "barcode" {
		trimmedBarcode := strings.TrimSpace(query)
		barcodeQuery := `
			SELECT id, shop_id, item_name, description, category, unit_of_measure, barcode, photo, selling_price, stock_quantity
			FROM inventory_items
			WHERE shop_id = $1 AND barcode = $2 AND deleted_at IS NULL
			LIMIT 1
		`
		var prod model.PublicProduct
		err := r.Resolver.DB.QueryRow(ctx, barcodeQuery, shopID, trimmedBarcode).Scan(
			&prod.ID, &prod.ShopID, &prod.ItemName, &prod.Description, &prod.Category,
			&prod.UnitOfMeasure, &prod.Barcode, &prod.Photo, &prod.SellingPrice, &prod.StockQuantity,
		)

		if err == pgx.ErrNoRows {
			return &model.PaginatedPublicProducts{Products: nil, TotalCount: 0, HasNextPage: false}, nil
		}
		if err != nil {
			log.Printf("🔴 SearchShopProducts: barcode mode query failed: %v", err)
			graphql.AddError(ctx, &gqlerror.Error{
				Message:    "internal server error: shop product search failure",
				Extensions: map[string]interface{}{"code": "INTERNAL_SERVER_ERROR"},
			})
			return nil, nil
		}

		score := 1.0
		matchType := "barcode"
		prod.MatchScore = &score
		prod.MatchType = &matchType
		return &model.PaginatedPublicProducts{
			Products:    []*model.PublicProduct{&prod},
			TotalCount:  1,
			HasNextPage: false,
		}, nil
	}

	// -------------------------------------------------------------------
	// LAYER 1: exact match against stable visual recognition keys.
	// These are bound once per item (see AddInventoryItem / UpdateInventoryItem)
	// from the vision model's own candidate names, so they're immune to the
	// shop owner renaming the item's display name later. Tried first because
	// it's a deterministic match, not a fuzzy guess.
	// -------------------------------------------------------------------
	if len(visualCandidates) > 0 {
		var visualCount int64
		visualCountQuery := `
			SELECT COUNT(*) FROM inventory_items
			WHERE shop_id = $1 AND deleted_at IS NULL AND visual_class_keys && $2
		`
		if err := r.Resolver.DB.QueryRow(ctx, visualCountQuery, shopID, visualCandidates).Scan(&visualCount); err != nil {
			log.Printf("🔴 SearchShopProducts: visual key count failed: %v", err)
			graphql.AddError(ctx, &gqlerror.Error{
				Message:    "internal server error: shop product search count failure",
				Extensions: map[string]interface{}{"code": "INTERNAL_SERVER_ERROR"},
			})
			return nil, nil
		}

		if visualCount > 0 {
			visualSelectQuery := `
				SELECT id, shop_id, item_name, description, category, unit_of_measure, photo, selling_price, stock_quantity
				FROM inventory_items
				WHERE shop_id = $1 AND deleted_at IS NULL AND visual_class_keys && $2
				ORDER BY item_name ASC
				LIMIT $3 OFFSET $4
			`
			rows, err := r.Resolver.DB.Query(ctx, visualSelectQuery, shopID, visualCandidates, limit, offset)
			if err != nil {
				log.Printf("🔴 SearchShopProducts: visual key select failed: %v", err)
				graphql.AddError(ctx, &gqlerror.Error{
					Message:    "internal server error: shop product collection search failure",
					Extensions: map[string]interface{}{"code": "INTERNAL_SERVER_ERROR"},
				})
				return nil, nil
			}
			defer rows.Close()

			var products []*model.PublicProduct
			for rows.Next() {
				var prod model.PublicProduct
				if err := rows.Scan(
					&prod.ID, &prod.ShopID, &prod.ItemName, &prod.Description, &prod.Category,
					&prod.UnitOfMeasure, &prod.Photo, &prod.SellingPrice, &prod.StockQuantity,
				); err != nil {
					graphql.AddError(ctx, &gqlerror.Error{
						Message:    "internal server error: shop item decoding failure",
						Extensions: map[string]interface{}{"code": "INTERNAL_SERVER_ERROR"},
					})
					return nil, nil
				}
				score := 1.0
				matchType := "visual_key"
				prod.MatchScore = &score
				prod.MatchType = &matchType
				products = append(products, &prod)
			}
			if err := rows.Err(); err != nil {
				return nil, err
			}

			return &model.PaginatedPublicProducts{
				Products:    products,
				TotalCount:  int(visualCount),
				HasNextPage: int64(offset+limit) < visualCount,
			}, nil
		}
		// No visual key hit — fall through to Layer 2 below rather than
		// returning empty, since the item may exist but just hasn't had a
		// key bound to it yet (e.g. it was created manually, never scanned).
	}

	// -------------------------------------------------------------------
	// LAYER 2: fuzzy text fallback — trigram similarity + substring match.
	// Used when no visualCandidates were supplied at all (manual typing),
	// or Layer 1 found nothing (new/never-seen product, or one without a
	// bound visual key yet).
	// -------------------------------------------------------------------
	const similarityThreshold = 0.2

	var totalCount int64
	countQuery := `
		SELECT COUNT(*) FROM inventory_items
		WHERE shop_id = $1 AND deleted_at IS NULL
		  AND (item_name ILIKE '%' || $2 || '%' OR category ILIKE '%' || $2 || '%' OR similarity(item_name, $2) > $3)
	`
	if err := r.Resolver.DB.QueryRow(ctx, countQuery, shopID, normalizedQuery, similarityThreshold).Scan(&totalCount); err != nil {
		graphql.AddError(ctx, &gqlerror.Error{
			Message:    "internal server error: shop product search count failure",
			Extensions: map[string]interface{}{"code": "INTERNAL_SERVER_ERROR"},
		})
		return nil, nil
	}

	selectQuery := `
		SELECT id, shop_id, item_name, description, category, unit_of_measure, photo, selling_price, stock_quantity,
		       GREATEST(similarity(item_name, $2), CASE WHEN item_name ILIKE '%' || $2 || '%' THEN 0.99 ELSE 0 END) AS score
		FROM inventory_items
		WHERE shop_id = $1 AND deleted_at IS NULL
		  AND (item_name ILIKE '%' || $2 || '%' OR category ILIKE '%' || $2 || '%' OR similarity(item_name, $2) > $3)
		ORDER BY score DESC, item_name ASC
		LIMIT $4 OFFSET $5
	`
	rows, err := r.Resolver.DB.Query(ctx, selectQuery, shopID, normalizedQuery, similarityThreshold, limit, offset)
	if err != nil {
		graphql.AddError(ctx, &gqlerror.Error{
			Message:    "internal server error: shop product collection search failure",
			Extensions: map[string]interface{}{"code": "INTERNAL_SERVER_ERROR"},
		})
		return nil, nil
	}
	defer rows.Close()

	var products []*model.PublicProduct
	for rows.Next() {
		var prod model.PublicProduct
		var score float64
		if err := rows.Scan(
			&prod.ID, &prod.ShopID, &prod.ItemName, &prod.Description, &prod.Category,
			&prod.UnitOfMeasure, &prod.Photo, &prod.SellingPrice, &prod.StockQuantity, &score,
		); err != nil {
			graphql.AddError(ctx, &gqlerror.Error{
				Message:    "internal server error: shop item decoding failure",
				Extensions: map[string]interface{}{"code": "INTERNAL_SERVER_ERROR"},
			})
			return nil, nil
		}
		matchType := "trgm_fallback"
		prod.MatchScore = &score
		prod.MatchType = &matchType
		products = append(products, &prod)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}

	return &model.PaginatedPublicProducts{
		Products:    products,
		TotalCount:  int(totalCount),
		HasNextPage: int64(offset+limit) < totalCount,
	}, nil
}

// GetShopDashboardMetrics is the resolver for the getShopDashboardMetrics field.
// GetShopDashboardMetrics is the resolver for the getShopDashboardMetrics field.
func (r *queryResolver) GetShopDashboardMetrics(ctx context.Context, shopID string) (*model.ShopDashboardMetrics, error) {
	// 1. SECURITY & AUTHN GATE
	currentUser, ok := ctx.Value("currentUser").(middleware.CachedUser)
	if !ok {
		graphql.AddError(ctx, &gqlerror.Error{
			Message:    "unauthorized: invalid authentication footprint",
			Extensions: map[string]interface{}{"code": "UNAUTHORIZED"},
		})
		return nil, nil
	}

	// Verify the caller is the actual owner of the shop
	if err := utils.EnsureShopOwnership(ctx, r.Resolver.DB, shopID, currentUser.ID); err != nil {
		utils.AddHistoryGraphQLError(ctx, err)
		return nil, nil
	}

	var metrics model.ShopDashboardMetrics

	// 2. WIDGET 1 & 2: CALCULATE MONDAY-TO-SUNDAY WEEKLY BREAKDOWNS + LOGGING VARIATION
	// Compares running totals of the current week (from Monday to now) against the full previous Mon-Sun week block.
	salesQuery := `
		WITH metrics_current_week AS (
			SELECT COALESCE(SUM(gross_sale), 0.0) as sales 
			FROM checkout_batches 
			WHERE shop_id = $1 
			  AND sold_at::timestamp >= DATE_TRUNC('week', CURRENT_DATE)
		),
		metrics_last_week AS (
			SELECT COALESCE(SUM(gross_sale), 0.0) as sales 
			FROM checkout_batches 
			WHERE shop_id = $1 
			  AND sold_at::timestamp >= DATE_TRUNC('week', CURRENT_DATE) - INTERVAL '7 days'
			  AND sold_at::timestamp < DATE_TRUNC('week', CURRENT_DATE)
		)
		SELECT 
			c.sales as this_week_sales,
			l.sales as last_week_sales,
			CASE WHEN l.sales = 0 THEN 0.0 ELSE ((c.sales - l.sales) / l.sales) * 100.0 END as growth_pct
		FROM metrics_current_week c, metrics_last_week l;
	`

	var thisWeekSales, lastWeekSales float64
	err := r.Resolver.DB.QueryRow(ctx, salesQuery, shopID).Scan(
		&thisWeekSales,
		&lastWeekSales,
		&metrics.TodaysSalesGrowthPct,
	)
	if err != nil {
		log.Printf("[DASHBOARD LOG] Error calculating weekly revenue metrics: %v", err)
		graphql.AddError(ctx, &gqlerror.Error{Message: "internal server error: revenue aggregation failure", Extensions: map[string]interface{}{"code": "INTERNAL_SERVER_ERROR"}})
		return nil, nil
	}

	// Assign the tracked revenue parameter into the return struct
	metrics.TodaysGrossSales = thisWeekSales

	// ADDED DICTIONARY LOGGING: Displays performance matrices inside your console tracker
	log.Printf("[DASHBOARD ANALYTICS] Shop ID: %s | This Week Total: ₱%.2f | Last Week Total: ₱%.2f | Computed Growth: %.2f%%",
		shopID, thisWeekSales, lastWeekSales, metrics.TodaysSalesGrowthPct)

	// 3. WIDGET 3: WEEKLY REVENUE GROWTH INDEX (This week vs Previous week)
	weeklyQuery := `
		WITH current_7_days AS (
			SELECT COALESCE(SUM(gross_sale), 0.0) as total 
			FROM checkout_batches 
			WHERE shop_id = $1 
			  AND sold_at::timestamp >= NOW() - INTERVAL '7 days'
		),
		previous_7_days AS (
			SELECT COALESCE(SUM(gross_sale), 0.0) as total 
			FROM checkout_batches 
			WHERE shop_id = $1 
			  AND sold_at::timestamp >= NOW() - INTERVAL '14 days' 
			  AND sold_at::timestamp < NOW() - INTERVAL '7 days'
		)
		SELECT CASE WHEN p.total = 0 THEN 100.0 ELSE (c.total / p.total) * 100.0 END 
		FROM current_7_days c, previous_7_days p;
	`
	err = r.Resolver.DB.QueryRow(ctx, weeklyQuery, shopID).Scan(&metrics.WeeklyRevenueGrowthIndex)
	if err != nil {
		log.Printf("Error calculating weekly revenue index: %v", err)
		graphql.AddError(ctx, &gqlerror.Error{Message: "internal server error: weekly trend compilation anomaly", Extensions: map[string]interface{}{"code": "INTERNAL_SERVER_ERROR"}})
		return nil, nil
	}

	// 4. WIDGET 4: AVERAGE TICKET SIZE (AOV)
	aovQuery := `
		SELECT COALESCE(AVG(gross_sale), 0.0) 
		FROM checkout_batches 
		WHERE shop_id = $1;
	`
	err = r.Resolver.DB.QueryRow(ctx, aovQuery, shopID).Scan(&metrics.AverageTicketSize)
	if err != nil {
		log.Printf("Error calculating average basket tickets: %v", err)
		graphql.AddError(ctx, &gqlerror.Error{Message: "internal server error: ticket computation anomaly", Extensions: map[string]interface{}{"code": "INTERNAL_SERVER_ERROR"}})
		return nil, nil
	}

	// 5. WIDGET 5: INVENTORY CAPITAL RATIO (Wholesale Cost vs Retail Value realization)
	// FIXED: Wrapped the SUM computations inside COALESCE statements to catch NULL variables for empty shops safely.
	capitalQuery := `
		SELECT 
			CASE 
				WHEN COALESCE(SUM(selling_price * stock_quantity), 0) = 0 THEN 0.0 
				ELSE (COALESCE(SUM(cost_price * stock_quantity), 0.0) / COALESCE(SUM(selling_price * stock_quantity), 0.0)) * 100.0 
			END 
		FROM inventory_items 
		WHERE shop_id = $1;
	`
	err = r.Resolver.DB.QueryRow(ctx, capitalQuery, shopID).Scan(&metrics.InventoryCapitalRatio)
	if err != nil {
		log.Printf("Error calculating capital realization parameters: %v", err)
		graphql.AddError(ctx, &gqlerror.Error{Message: "internal server error: resource analysis failure", Extensions: map[string]interface{}{"code": "INTERNAL_SERVER_ERROR"}})
		return nil, nil
	}

	// 6. WIDGET 6: PAST 7-DAY SALES HISTORY TREND ENGINE
	trendQuery := `
		WITH RECURSIVE days AS (
			SELECT CURRENT_DATE - INTERVAL '6 days' AS calendar_day
			UNION ALL
			SELECT calendar_day + INTERVAL '1 day' FROM days WHERE calendar_day < CURRENT_DATE
		),
		daily_sales AS (
			SELECT 
				sold_at::date AS sales_day,
				COALESCE(SUM(gross_sale), 0.0) AS total_sales,
				COALESCE(SUM(gross_profit), 0.0) AS total_profit
			FROM checkout_batches 
			WHERE shop_id = $1 
			  AND sold_at::timestamp >= CURRENT_DATE - INTERVAL '6 days'
			GROUP BY sales_day
		)
		SELECT 
			TO_CHAR(d.calendar_day, 'Dy') AS day_name,
			TO_CHAR(d.calendar_day, 'MM/DD') AS formatted_date,
			COALESCE(s.total_sales, 0.0) AS gross_sale,
			COALESCE(s.total_profit, 0.0) AS gross_profit
		FROM days d
		LEFT JOIN daily_sales s ON d.calendar_day = s.sales_day
		ORDER BY d.calendar_day ASC;
	`
	rows, err := r.Resolver.DB.Query(ctx, trendQuery, shopID)
	if err != nil {
		log.Printf("Weekly chart matrix extraction failure: %v", err)
		graphql.AddError(ctx, &gqlerror.Error{Message: "internal server error: weekly trend compilation failure", Extensions: map[string]interface{}{"code": "INTERNAL_SERVER_ERROR"}})
		return nil, nil
	}
	defer rows.Close()

	var weeklySalesTrend []*model.DailySalesMetric
	for rows.Next() {
		var dayMetric model.DailySalesMetric
		err := rows.Scan(
			&dayMetric.DayName,
			&dayMetric.FormattedDate,
			&dayMetric.GrossSale,
			&dayMetric.GrossProfit,
		)
		if err != nil {
			log.Printf("Error decoding weekly trend data frames: %v", err)
			return nil, err
		}
		weeklySalesTrend = append(weeklySalesTrend, &dayMetric)
	}

	if err := rows.Err(); err != nil {
		return nil, err
	}

	metrics.WeeklySalesTrend = weeklySalesTrend
	return &metrics, nil
}
